import type { leases, payments } from '@/generated/prisma/client'
import { forbidden, notFound } from '@/lib/errors'
import { prisma } from '@/lib/prisma'

export type MemberRole = 'manager' | 'staff'
export type AccessRole = MemberRole | 'tenant'

export type Caller = {
  userId: string
  member: { orgId: string; role: MemberRole } | null
  tenantIds: string[]
}

// Shape check only; a well-formed id that does not exist is still a 404 after the lookup (R38).
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export function isUuid(v: unknown): v is string {
  return typeof v === 'string' && UUID_RE.test(v)
}

function isMemberRole(role: string): role is MemberRole {
  return role === 'manager' || role === 'staff'
}

// R37/D17: roles come only from memberships (staff/manager, one org per user) and tenants.user_id;
// never from user_metadata or anything else the user can edit.
export async function loadCaller(userId: string): Promise<Caller> {
  const [membership, tenantRows] = await Promise.all([
    prisma.memberships.findUnique({ where: { user_id: userId }, select: { org_id: true, role: true } }),
    prisma.tenants.findMany({ where: { user_id: userId }, select: { id: true } }),
  ])
  const member = membership && isMemberRole(membership.role) ? { orgId: membership.org_id, role: membership.role } : null
  return { userId, member, tenantIds: tenantRows.map((t) => t.id) }
}

// For endpoints with no target record (POST /api/leases, reports): not a listed member role -> 403.
export function requireMember(caller: Caller, roles: MemberRole[]): { orgId: string; role: MemberRole } {
  if (!caller.member || !roles.includes(caller.member.role)) throw forbidden()
  return caller.member
}

// The roles under which the caller can see a lease: member of its org, and/or its tenant.
export function rolesOnLease(caller: Caller, lease: { org_id: string; tenant_id: string }): AccessRole[] {
  const result: AccessRole[] = []
  if (caller.member && caller.member.orgId === lease.org_id) result.push(caller.member.role)
  if (caller.tenantIds.includes(lease.tenant_id)) result.push('tenant')
  return result
}

// R38 order: not visible (malformed id, nonexistent, other org, other tenant's lease) -> 404 first,
// so existence is never revealed; visible but no allowed role -> 403.
function checkLease(caller: Caller, lease: leases | null, roles: AccessRole[], what: string): leases {
  if (!lease) throw notFound(`${what} not found`)
  const visibleAs = rolesOnLease(caller, lease)
  if (visibleAs.length === 0) throw notFound(`${what} not found`)
  if (!visibleAs.some((r) => roles.includes(r))) throw forbidden()
  return lease
}

export async function requireLeaseAccess(caller: Caller, leaseId: string, roles: AccessRole[]): Promise<leases> {
  if (!isUuid(leaseId)) throw notFound('Lease not found')
  const lease = await prisma.leases.findUnique({ where: { id: leaseId } })
  return checkLease(caller, lease, roles, 'Lease')
}

export async function requirePaymentAccess(caller: Caller, paymentId: string, roles: AccessRole[]): Promise<payments> {
  if (!isUuid(paymentId)) throw notFound('Payment not found')
  const payment = await prisma.payments.findUnique({ where: { id: paymentId } })
  if (!payment) throw notFound('Payment not found')
  // Scoped by the payment's own org_id, so a mismatched row can never widen visibility.
  const lease = await prisma.leases.findFirst({ where: { id: payment.lease_id, org_id: payment.org_id } })
  checkLease(caller, lease, roles, 'Payment')
  return payment
}
import { badRequest, toErrorResponse } from '@/lib/errors'

// Wraps a route handler so every thrown error becomes the SPEC error body (D2), never a stack trace.
export function route<C>(handler: (req: Request, ctx: C) => Promise<Response>): (req: Request, ctx: C) => Promise<Response> {
  return async (req, ctx) => {
    try {
      return await handler(req, ctx)
    } catch (e) {
      return toErrorResponse(e)
    }
  }
}

export function json(body: unknown, status = 200): Response {
  return Response.json(body, { status })
}

// R45: request bodies are JSON objects; anything else is a 400 before validation.
export async function readJson(req: Request): Promise<Record<string, unknown>> {
  let text: string
  try {
    text = await req.text()
  } catch {
    throw badRequest('Could not read the request body')
  }
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    throw badRequest('Malformed JSON body')
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw badRequest('Request body must be a JSON object')
  }
  return parsed as Record<string, unknown>
}
import { createClient as createSupabaseClient, type SupabaseClient } from '@supabase/supabase-js'
import { unauthorized } from '@/lib/errors'
import { createClient as createCookieClient, publishableKey, supabaseUrl } from '@/lib/supabase/server'

const BEARER_RE = /^Bearer\s+(\S+)\s*$/i

let tokenClient: SupabaseClient | undefined

// Stateless client used only to validate a caller-supplied access token with the Auth server.
function getTokenClient(): SupabaseClient {
  tokenClient ??= createSupabaseClient(supabaseUrl(), publishableKey(), {
    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
  })
  return tokenClient
}

// R37/R40: identity comes from auth.getUser() (verified by the Auth server), never getSession().
// A Bearer header, when present, is the only credential considered: an invalid token is a 401 even if
// a session cookie is also sent.
export async function getUserId(req?: Request): Promise<string | null> {
  const header = req?.headers.get('authorization')
  const bearer = header ? BEARER_RE.exec(header) : null
  if (bearer) {
    const { data, error } = await getTokenClient().auth.getUser(bearer[1])
    return error || !data.user ? null : data.user.id
  }
  const supabase = await createCookieClient()
  const { data, error } = await supabase.auth.getUser()
  return error || !data.user ? null : data.user.id
}

export async function requireUserId(req?: Request): Promise<string> {
  const userId = await getUserId(req)
  if (!userId) throw unauthorized('Unauthorized')
  return userId
}
import { ZodError } from 'zod'

// D2: every error body is { "error": "<message>" }, a plain string (brief section 7).
export class ApiError extends Error {
  readonly status: number

  constructor(status: number, message: string) {
    super(message)
    this.name = 'ApiError'
    this.status = status
  }
}

export const badRequest = (msg = 'Invalid input') => new ApiError(400, msg)
export const unauthorized = (msg = 'Unauthorized') => new ApiError(401, msg)
export const forbidden = (msg = 'Forbidden') => new ApiError(403, msg)
export const notFound = (msg = 'Not found') => new ApiError(404, msg)
export const conflict = (msg = 'Conflict') => new ApiError(409, msg)
export const unprocessable = (msg = 'Unprocessable') => new ApiError(422, msg)

export function errorResponse(status: number, message: string): Response {
  return Response.json({ error: message }, { status })
}

type PgError = { code: string; message: string }

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null
}

// Finds the Postgres SQLSTATE behind an error, wherever the stack put it:
// - Prisma 7 + adapter-pg: PrismaClientKnownRequestError.meta.driverAdapterError.cause.{originalCode, originalMessage}
//   ($queryRaw failures arrive as P2010 with the real SQLSTATE only there);
// - a bare DriverAdapterError (.cause.originalCode), or a pg DatabaseError (.code + .severity).
function findPgError(e: unknown, depth = 0): PgError | null {
  if (!isRecord(e) || depth > 4) return null
  if (typeof e.originalCode === 'string') {
    return { code: e.originalCode, message: typeof e.originalMessage === 'string' ? e.originalMessage : '' }
  }
  if (typeof e.code === 'string' && /^[0-9A-Z]{5}$/.test(e.code) && typeof e.severity === 'string') {
    return { code: e.code, message: typeof e.message === 'string' ? e.message : '' }
  }
  if (isRecord(e.meta)) {
    const found = findPgError(e.meta.driverAdapterError, depth + 1)
    if (found) return found
  }
  return findPgError(e.cause, depth + 1)
}

function prismaCode(e: unknown): string | null {
  return isRecord(e) && typeof e.code === 'string' && /^P\d{4}$/.test(e.code) ? e.code : null
}

const RETRYABLE_SQLSTATES = new Set(['40001', '40P01'])

export function isRetryable(e: unknown): boolean {
  const pg = findPgError(e)
  if (pg) return RETRYABLE_SQLSTATES.has(pg.code)
  return prismaCode(e) === 'P2034'
}

// Error contract: serialization failure / deadlock is retried once, then surfaces as 409.
export async function withRetry<T>(fn: () => Promise<T>): Promise<T> {
  try {
    return await fn()
  } catch (e) {
    if (!isRetryable(e)) throw e
    return fn()
  }
}

function zodMessage(e: ZodError): string {
  const issue = e.issues[0]
  if (!issue) return 'Invalid input'
  const path = issue.path.map(String).join('.')
  return path ? `Invalid input: ${path}: ${issue.message}` : `Invalid input: ${issue.message}`
}

const DB_CODE_STATUS: Record<string, { status: number; message: string | null }> = {
  // private.* functions raise these with a human message that is safe to show (SPEC money functions).
  P0400: { status: 400, message: null },
  P0404: { status: 404, message: null },
  P0409: { status: 409, message: null },
  P0422: { status: 422, message: null },
  '23P01': { status: 409, message: 'Lease overlaps another lease on this unit' }, // D16
  '23505': { status: 409, message: 'Conflict with an existing record' },
  '22P02': { status: 400, message: 'Invalid input' },
  '22007': { status: 400, message: 'Invalid input' },
  '22008': { status: 400, message: 'Invalid input' },
  '23503': { status: 400, message: 'Invalid reference' },
  '23514': { status: 400, message: 'Invalid input' },
  '23502': { status: 400, message: 'Invalid input' },
  '40001': { status: 409, message: 'Conflict with a concurrent request, please retry' },
  '40P01': { status: 409, message: 'Conflict with a concurrent request, please retry' },
}

const PRISMA_CODE_STATUS: Record<string, { status: number; message: string }> = {
  P2002: { status: 409, message: 'Conflict with an existing record' },
  P2025: { status: 404, message: 'Not found' },
  P2023: { status: 400, message: 'Invalid input' },
  P2003: { status: 400, message: 'Invalid reference' },
  P2034: { status: 409, message: 'Conflict with a concurrent request, please retry' },
}

export function toErrorResponse(e: unknown): Response {
  if (e instanceof ApiError) return errorResponse(e.status, e.message)
  if (e instanceof ZodError) return errorResponse(400, zodMessage(e))

  const pg = findPgError(e)
  if (pg) {
    const mapped = DB_CODE_STATUS[pg.code]
    if (mapped) {
      const fallback = mapped.status === 404 ? 'Not found' : 'Invalid request'
      return errorResponse(mapped.status, mapped.message ?? (pg.message.trim() || fallback))
    }
  }
  const pc = prismaCode(e)
  if (pc && PRISMA_CODE_STATUS[pc]) {
    const { status, message } = PRISMA_CODE_STATUS[pc]
    return errorResponse(status, message)
  }

  // Generic 500: only the error class and code are logged (no payloads, no SQL, no secrets).
  const name = isRecord(e) && typeof e.name === 'string' ? e.name : typeof e
