  const [y, mo, d, h, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number)
  const sec = m[6] ?? '00'
  if (!validParts(y, mo, d, h, mi, Number(sec))) throw new Error('Not a real date-time')
  return `${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${sec}+08:00`
